<?php require 'app/init.php';require 'app/view.php';$u=require_user();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify();$contenido=trim($_POST['contenido']??'');if(!$contenido||mb_strlen($contenido)>10000)throw new Exception('El contenido debe tener entre 1 y 10000 caracteres.');$img=null;if(!empty($_FILES['imagen']['name'])){$f=$_FILES['imagen'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3*1024*1024)throw new Exception('Imagen inválida o mayor de 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new Exception('Solo JPG, PNG o WEBP.');$img='uploads/'.bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],__DIR__.'/'.$img))throw new Exception('No se pudo guardar la imagen.');}$tipo=$_POST['tipo']??'texto';if(!in_array($tipo,['texto','resena','frase','foto'],true))$tipo='texto';$s=db()->prepare('INSERT INTO publicaciones(usuario_id,libro_id,tipo,titulo,contenido,imagen,calificacion) VALUES(?,?,?,?,?,?,?)');$s->execute([$u['id'],($_POST['libro_id']??'')?:null,$tipo,trim($_POST['titulo']??'')?:null,$contenido,$img,($_POST['calificacion']??'')?:null]);go();}catch(Throwable $ex){$error=$ex->getMessage();}}top('Publicar');?><main class="card" style="max-width:740px;margin:35px auto"><h1>Crear publicación</h1><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-row"><select name="tipo"><?php foreach(['texto'=>'Texto','resena'=>'Reseña','frase'=>'Frase','foto'=>'Foto'] as $k=>$v):?><option value="<?=$k?>" <?=($_GET['tipo']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="form-row"><input class="field" name="titulo" maxlength="220" placeholder="Título (opcional)"></div><div class="form-row"><textarea name="contenido" required maxlength="10000" placeholder="¿Qué te dejó tu última lectura?"></textarea></div><div class="form-row"><select name="libro_id"><option value="">Sin libro asociado</option><?php foreach(db()->query('SELECT id,titulo FROM libros ORDER BY titulo') as $b):?><option value="<?=$b['id']?>"><?=e($b['titulo'])?></option><?php endforeach;?></select></div><div class="form-row"><select name="calificacion"><option value="">Sin calificación</option><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>"><?=$i?> estrellas</option><?php endfor;?></select></div><div class="form-row"><input type="file" name="imagen" accept="image/jpeg,image/png,image/webp"></div><button>Publicar</button></form></main><?php bottom();?>